void incByValue(int x) { x++; }
void incByRef(int& x) { x++; }

int main() {
    int a = 5;
    incByValue(a);
    cout << a << endl; // 5, unchanged
    incByRef(a);
    cout << a << endl; // 6, changed
    return 0;
